_B = -2.10387
# how much a blunder-probability point is worth against policy probability
_K = 2.2


class Player:
    def __init__(self, oracle, budget):
        self.oracle = oracle
        self.budget = budget
        self.last = None

    def play(self, board, pgn):
        pol, acts = self.oracle.policy_with_acts(board, pgn, layer=11)
        if not pol:
            return next(iter(board.legal_moves), None)
        ranked = sorted(pol, key=pol.get, reverse=True)[:6]
        best, best_s = None, -1e9
        rows = []
        for mv in ranked:
            a = acts[mv]
            z = _B
            for i in range(len(_W)):
                z += _W[i] * a[i]
            risk = 1.0 / (1.0 + 2.718281828 ** (-z))   # P(blunder)
            s = pol[mv] - _K * risk
            rows.append((mv, pol[mv], risk, s))
            if s > best_s:
                best_s, best = s, mv
        self.last = rows
        return best


def create_player(oracle, budget):
    return Player(oracle, budget)
